window.__OPENSTAX_PHYSICS__[13] = {"schemaVersion":"4.0.0-physics","generatedAt":"2026-11-27T01:33:30.761Z","number":13,"code":"ch13","slug":"waves-and-their-properties","title":"Waves and Their Properties","titleVi":"Sóng Cơ & Tính Chất Của Sóng (Waves & Their Properties)","sections":[{"uid":"hsphys.ch13.sec00","moduleId":"m54312","number":"13.0","slug":"introduction","title":"Introduction","isIntroduction":true,"learningObjectives":[],"bilingualGuide":null,"keyEquations":[],"subsections":[{"uid":"hsphys.ch13.sec00.sub01","title":"Chapter Introduction","summaryVi":null,"paragraphs":["Recall from the chapter on Motion in Two Dimensions that oscillations—the back-and-forth movement between two points—involve force and energy. Some oscillations create waves, such as the sound waves created by plucking a guitar string. Other examples of waves include earthquakes and visible light. Even subatomic particles, such as electrons, can behave like waves. You can make water waves in a swimming pool by slapping the water with your hand. Some of these waves, such as water waves, are visible; others, such as sound waves, are not. But every wave is a disturbance that moves from its source and carries energy. In this chapter, we will learn about the different types of waves, their properties, and how they interact with one another."],"figures":[{"sourceId":"fs-id1167065071704","filename":"CNX_HSPhysics_13_00_Ocean.jpg","relativePath":"media/CNX_HSPhysics_13_00_Ocean.jpg","alt":"An ocean whitecap crashes near two surfers and three boats."}],"tables":[]}],"workedExamples":[],"snapLabs":[],"tipsAndFeatures":[],"summaryPoints":[],"glossary":[],"assessments":[],"stats":{"learningObjectiveCount":0,"keyEquationCount":0,"subsectionCount":1,"workedExampleCount":0,"snapLabCount":0,"glossaryCount":0,"assessmentCount":0}},{"uid":"hsphys.ch13.sec01","moduleId":"m54314","number":"13.1","slug":"types-of-waves","title":"Types of Waves","isIntroduction":false,"learningObjectives":["Define mechanical waves and medium, and relate the two","Distinguish a pulse wave from a periodic wave","Distinguish a longitudinal wave from a transverse wave and give examples of such waves"],"bilingualGuide":{"notebookSummaryVi":"Phân biệt Sóng ngang (Transverse — dao động vuông góc phương truyền) và Sóng dọc (Longitudinal — dao động trùng phương truyền).","wordProblemCues":[{"phraseEn":"transverse vs longitudinal","meaningVi":"Sóng ngang vs Sóng dọc","mathNotation":"⊥ vs ∥"}],"commonTrapsVi":["Sóng truyền NĂNG LƯỢNG đi xa, KHÔNG kéo các phân tử nước hay không khí đi theo sóng!"]},"keyEquations":[],"subsections":[{"uid":"hsphys.ch13.sec01.sub01","title":"Mechanical Waves","summaryVi":null,"paragraphs":["What do we mean when we say something is a wave? A wave is a disturbance that travels or propagates from the place where it was created. Waves transfer energy from one place to another, but they do not necessarily transfer any mass. Light, sound, and waves in the ocean are common examples of waves. Sound and water waves are mechanical waves ; meaning, they require a medium to travel through. The medium may be a solid, a liquid, or a gas, and the speed of the wave depends on the material properties of the medium through which it is traveling. However, light is not a mechanical wave; it can travel through a vacuum such as the empty parts of outer space.","A familiar wave that you can easily imagine is the water wave. For water waves, the disturbance is in the surface of the water, an example of which is the disturbance created by a rock thrown into a pond or by a swimmer splashing the water surface repeatedly. For sound waves, the disturbance is caused by a change in air pressure, an example of which is when the oscillating cone inside a speaker creates a disturbance. For earthquakes, there are several types of disturbances, which include the disturbance of Earth’s surface itself and the pressure disturbances under the surface. Even radio waves are most easily understood using an analogy with water waves. Because water waves are common and visible, visualizing water waves may help you in studying other types of waves, especially those that are not visible.","Water waves have characteristics common to all waves, such as amplitude , period , frequency , and energy , which we will discuss in the next section."],"figures":[],"tables":[]},{"uid":"hsphys.ch13.sec01.sub02","title":"Pulse Waves and Periodic Waves","summaryVi":null,"paragraphs":["If you drop a pebble into the water, only a few waves may be generated before the disturbance dies down, whereas in a wave pool, the waves are continuous. A pulse wave is a sudden disturbance in which only one wave or a few waves are generated, such as in the example of the pebble. Thunder and explosions also create pulse waves. A periodic wave repeats the same oscillation for several cycles, such as in the case of the wave pool, and is associated with simple harmonic motion. Each particle in the medium experiences simple harmonic motion in periodic waves by moving back and forth periodically through the same positions.","Consider the simplified water wave in [Figure 13.1]. This wave is an up-and-down disturbance of the water surface, characterized by a sine wave pattern. The uppermost position is called the crest and the lowest is the trough . It causes a seagull to move up and down in simple harmonic motion as the wave crests and troughs pass under the bird."],"figures":[{"sourceId":"fs-id1167066042408","filename":"CNX_HSPhysics_13_01_SimpleWave.jpg","relativePath":"media/CNX_HSPhysics_13_01_SimpleWave.jpg","alt":"A seagull bobs up and down on a sine-wave-shaped periodic ocean wave."}],"tables":[]},{"uid":"hsphys.ch13.sec01.sub03","title":"Longitudinal Waves and Transverse Waves","summaryVi":null,"paragraphs":["Mechanical waves are categorized by their type of motion and fall into any of two categories: transverse or longitudinal. Note that both transverse and longitudinal waves can be periodic. A transverse wave propagates so that the disturbance is perpendicular to the direction of propagation. An example of a transverse wave is shown in [Figure 13.1], where a woman moves a toy spring up and down, generating waves that propagate away from herself in the horizontal direction while disturbing the toy spring in the vertical direction.","In contrast, in a longitudinal wave , the disturbance is parallel to the direction of propagation. [Figure 13.1] shows an example of a longitudinal wave, where the woman now creates a disturbance in the horizontal direction—which is the same direction as the wave propagation—by stretching and then compressing the toy spring.","Waves may be transverse, longitudinal, or a combination of the two . The waves on the strings of musical instruments are transverse (as shown in [Figure 13.1]), and so are electromagnetic waves, such as visible light. Sound waves in air and water are longitudinal. Their disturbances are periodic variations in pressure that are transmitted in fluids.","Sound in solids can be both longitudinal and transverse. Essentially, water waves are also a combination of transverse and longitudinal components, although the simplified water wave illustrated in [Figure 13.1] does not show the longitudinal motion of the bird.","Earthquake waves under Earth’s surface have both longitudinal and transverse components as well. The longitudinal waves in an earthquake are called pressure or P-waves, and the transverse waves are called shear or S-waves. These components have important individual characteristics; for example, they propagate at different speeds. Earthquakes also have surface waves that are similar to surface waves on water.","Many people enjoy surfing in the ocean. For some surfers, the bigger the wave, the better. In one area off the coast of central California, waves can reach heights of up to 50 feet in certain times of the year ([Figure 13.1]).","How do waves reach such extreme heights? Other than unusual causes, such as when earthquakes produce tsunami waves, most huge waves are caused simply by interactions between the wind and the surface of the water. The wind pushes up against the surface of the water and transfers energy to the water in the process. The stronger the wind, the more energy transferred. As waves start to form, a larger surface area becomes in contact with the wind, and even more energy is transferred from the wind to the water, thus creating higher waves. Intense storms create the fastest winds, kicking up massive waves that travel out from the origin of the storm. Longer-lasting storms and those storms that affect a larger area of the ocean create the biggest waves since they transfer more energy. The cycle of the tides from the Moon’s gravitational pull also plays a small role in creating waves.","Actual ocean waves are more complicated than the idealized model of the simple transverse wave with a perfect sinusoidal shape. Ocean waves are examples of orbital progressive waves , where water particles at the surface follow a circular path from the crest to the trough of the passing wave, then cycle back again to their original position. This cycle repeats with each passing wave.","As waves reach shore, the water depth decreases and the energy of the wave is compressed into a smaller volume. This creates higher waves—an effect known as shoaling .","Since the water particles along the surface move from the crest to the trough, surfers hitch a ride on the cascading water, gliding along the surface. If ocean waves work exactly like the idealized transverse waves, surfing would be much less exciting as it would simply involve standing on a board that bobs up and down in place, just like the seagull in the previous figure.","Additional information and illustrations about the scientific principles behind surfing can be found in the “Using Science to Surf Better!” video."],"figures":[{"sourceId":"fs-id1167064825327","filename":"CNX_HSPhysics_13_01_TransverseWave.jpg","relativePath":"media/CNX_HSPhysics_13_01_TransverseWave.jpg","alt":"A woman moves a slinky up and down, creating transverse waves that propagate horizontally away from her while disturbing the slinky vertically."},{"sourceId":"fs-id1167066035396","filename":"CNX_HSPhysics_13_01_Longitudin.jpg","relativePath":"media/CNX_HSPhysics_13_01_Longitudin.jpg","alt":"A woman stretches and compresses a slinky horizontally, creating longitudinal waves that propagate horizontally away from her and disturbing the slinky horizontally as well."},{"sourceId":"fs-id1167065953592","filename":"CNX_HSPhysics_13_01_GuitarWave.jpg","relativePath":"media/CNX_HSPhysics_13_01_GuitarWave.jpg","alt":"A guitar string is disturbed vertically but travels horizontally. Sound travels from the guitar, through an amplifier, out of a speaker, and to a piece of paper, which vibrates back and forth with the waves of compression."},{"sourceId":"fs-id1167064903696","filename":"CNX_HSPhysics_13_01_Surfers.jpg","relativePath":"media/CNX_HSPhysics_13_01_Surfers.jpg","alt":"A surfer glides down a giant wave while another surfer watches from the wave’s crest."}],"tables":[]}],"workedExamples":[],"snapLabs":[],"tipsAndFeatures":[{"uid":"hsphys.ch13.sec01.feat01","type":"tip","title":"Tips for Success","text":"Longitudinal waves are sometimes called compression waves or compressional waves , and transverse waves are sometimes called shear waves .","images":[]}],"summaryPoints":["A wave is a disturbance that moves from the point of creation and carries energy but not mass.","Mechanical waves must travel through a medium.","Sound waves, water waves, and earthquake waves are all examples of mechanical waves.","Light is not a mechanical wave since it can travel through a vacuum.","A periodic wave is a wave that repeats for several cycles, whereas a pulse wave has only one crest or a few crests and is associated with a sudden disturbance.","Periodic waves are associated with simple harmonic motion.","A transverse wave has a disturbance perpendicular to its direction of propagation, whereas a longitudinal wave has a disturbance parallel to its direction of propagation."],"glossary":[{"term":"longitudinal wave","termVi":"Sóng dọc","definition":"wave in which the disturbance is parallel to the direction of propagation","definitionVi":"Sóng có phương dao động TRÙNG với phương truyền sóng (tạo vùng nén – dãn, như sóng âm trong không khí).","memoryTipVi":"Long-itudinal = dọc theo phương truyền."},{"term":"mechanical wave","termVi":"Sóng cơ học","definition":"wave that requires a medium through which it can travel","definitionVi":"Sóng cần môi trường vật chất (rắn, lỏng, khí) để lan truyền — không truyền được trong chân không.","memoryTipVi":"Ví dụ: sóng nước, sóng âm, sóng trên dây."},{"term":"medium","termVi":"Môi trường truyền sóng","definition":"solid, liquid, or gas material through which a wave propagates","definitionVi":"Vật chất (không khí, nước, kim loại...) mà sóng cơ lan truyền qua.","memoryTipVi":"Số nhiều là Media."},{"term":"periodic wave","termVi":"Sóng tuần hoàn","definition":"wave that repeats the same oscillation for several cycles and is associated with simple harmonic motion","definitionVi":"Sóng lặp lại đều đặn sau những khoảng thời gian bằng nhau (chu kỳ T).","memoryTipVi":"Có chu kỳ T và tần số f xác định."},{"term":"pulse wave","termVi":"Xung sóng (Sóng đơn)","definition":"sudden disturbance with only one wave or a few waves generated","definitionVi":"Một nhiễu động đơn lẻ lan truyền qua môi trường (như vẩy dây một cái rồi dừng).","memoryTipVi":"Không lặp lại tuần hoàn."},{"term":"transverse wave","termVi":"Sóng ngang","definition":"wave in which the disturbance is perpendicular to the direction of propagation","definitionVi":"Sóng có phương dao động VUÔNG GÓC với phương truyền sóng (như sóng trên dây, sóng ánh sáng).","memoryTipVi":"Trans-verse = cắt ngang (vuông góc)."},{"term":"wave","termVi":"Sóng","definition":"disturbance that moves from its source and carries energy","definitionVi":"Sự lan truyền dao động (và năng lượng) trong không gian theo thời gian mà KHÔNG truyền theo phần tử vật chất.","memoryTipVi":"Sóng truyền NĂNG LƯỢNG, các phần tử môi trường chỉ dao động tại chỗ!"}],"assessments":[{"uid":"hsphys.ch13.sec01.q005","sourceId":"fs-id1167064932437","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"What are the categories of mechanical waves based on the type of motion?","images":[],"choices":[{"label":"a","text":"Both transverse and longitudinal waves"},{"label":"b","text":"Only longitudinal waves"},{"label":"c","text":"Only transverse waves"},{"label":"d","text":"Only surface waves"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch13.sec01.q006","sourceId":"fs-id1167065001419","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"In which direction do the particles of the medium oscillate in a transverse wave?","images":[],"choices":[{"label":"a","text":"Perpendicular to the direction of propagation of the transverse wave"},{"label":"b","text":"Parallel to the direction of propagation of the transverse wave"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch13.sec01.q009","sourceId":"fs-id1167064726908","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"Which of the examples is closest to being purely a longitudinal wave?","images":[],"choices":[{"label":"a","text":"light waves"},{"label":"b","text":"water waves in a lake"},{"label":"c","text":"sound waves in air"},{"label":"d","text":"seismic waves in Earths surface"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch13.sec01.q011","sourceId":"fs-id1167066145951","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"Give an example of a wave that propagates only through a solid.","images":[],"choices":[{"label":"a","text":"Light wave"},{"label":"b","text":"Sound wave"},{"label":"c","text":"Seismic wave"},{"label":"d","text":"Surface wave"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch13.sec01.q012","sourceId":"fs-id1167064901320","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"Can mechanical waves be periodic waves?","images":[],"choices":[{"label":"a","text":"No, mechanical waves cannot be periodic waves."},{"label":"b","text":"Yes, mechanical waves can be periodic."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch13.sec01.q015","sourceId":"fs-id1167064780807","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"What kind of waves are sound waves?","images":[],"choices":[{"label":"a","text":"Mechanical waves"},{"label":"b","text":"Electromagnetic waves"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch13.sec01.q016","sourceId":"fs-id1167064817903","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"What kind of a wave does a tuning fork create?","images":[],"choices":[{"label":"a","text":"Pulse wave"},{"label":"b","text":"Periodic wave"},{"label":"c","text":"Electromagnetic wave"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch13.sec01.q017","sourceId":"fs-id1167064960964","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"What kind of waves are electromagnetic waves?","images":[],"choices":[{"label":"a","text":"Longitudinal waves"},{"label":"b","text":"Transverse waves"},{"label":"c","text":"Mechanical waves"},{"label":"d","text":"P-waves"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch13.sec01.q018","sourceId":"eip-id1166851008098","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"With reference to waves, what is a disturbance?","images":[],"choices":[{"label":"a","text":"It refers to the resistance produced by some particles of a material."},{"label":"b","text":"It refers to an oscillation produced by some energy that creates a wave."},{"label":"c","text":"It refers to the wavelength of the wave."},{"label":"d","text":"It refers to the speed of the wave."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch13.sec01.q019","sourceId":"fs-id1167065770189","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"Give an example of a non-mechanical wave.","images":[],"choices":[{"label":"a","text":"A radio wave is an example of a nonmechanical wave."},{"label":"b","text":"A sound wave is an example of a nonmechanical wave."},{"label":"c","text":"A surface wave is an example of a nonmechanical wave."},{"label":"d","text":"A seismic wave is an example of a nonmechanical wave."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch13.sec01.q021","sourceId":"fs-id1167062408823","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"What kind of wave is thunder?","images":[],"choices":[{"label":"a","text":"Transverse wave"},{"label":"b","text":"Pulse wave"},{"label":"c","text":"R-wave"},{"label":"d","text":"P-wave"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch13.sec01.q024","sourceId":"fs-id1167064733812","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"Give an example of orbital progressive waves.","images":[],"choices":[{"label":"a","text":"light waves"},{"label":"b","text":"ocean waves"},{"label":"c","text":"sound waves"},{"label":"d","text":"seismic waves"}],"hasOfficialSolution":false,"solution":null}],"stats":{"learningObjectiveCount":3,"keyEquationCount":0,"subsectionCount":3,"workedExampleCount":0,"snapLabCount":0,"glossaryCount":7,"assessmentCount":12}},{"uid":"hsphys.ch13.sec02","moduleId":"m54321","number":"13.2","slug":"wave-properties-speed-amplitude-frequency-and-period","title":"Wave Properties: Speed, Amplitude, Frequency, and Period","isIntroduction":false,"learningObjectives":["Define amplitude, frequency, period, wavelength, and velocity of a wave","Relate wave frequency, period, wavelength, and velocity","Solve problems involving wave properties"],"bilingualGuide":{"notebookSummaryVi":"Công thức vàng của Sóng: v = λ · f = λ / T (Tốc độ = Bước sóng × Tần số).","wordProblemCues":[{"phraseEn":"wave speed v = fλ","meaningVi":"Tốc độ sóng = Tần số × Bước sóng","mathNotation":"v = f·λ"}],"commonTrapsVi":["Tăng tần số f KHÔNG làm tăng tốc độ sóng v trong cùng một môi trường — nó chỉ làm giảm bước sóng λ!"]},"keyEquations":[{"name":"wave velocity","formula":"\\({v}_{\\text{w}} = \\frac{\\lambda}{T}\\) or \\({v}_{\\text{w}} = f\\lambda\\)"},{"name":"period","formula":"\\(T = \\frac{1}{f}\\)"},{"name":"frequency","formula":"\\(f = \\frac{1}{T}\\)"}],"subsections":[{"uid":"hsphys.ch13.sec02.sub01","title":"Wave Variables","summaryVi":null,"paragraphs":["In the chapter on motion in two dimensions, we defined the following variables to describe harmonic motion:","For waves, these variables have the same basic meaning. However, it is helpful to word the definitions in a more specific way that applies directly to waves:","In addition to amplitude, frequency, and period, their wavelength and wave velocity also characterize waves. The wavelength \\(\\lambda\\) is the distance between adjacent identical parts of a wave, parallel to the direction of propagation. The wave velocity \\({v}_{w}\\) is the speed at which the disturbance moves.","Consider the periodic water wave in [Figure 13.2]. Its wavelength is the distance from crest to crest or from trough to trough. The wavelength can also be thought of as the distance a wave has traveled after one complete cycle—or one period. The time for one complete up-and-down motion is the simple water wave’s period T . In the figure, the wave itself moves to the right with a wave velocity v w . Its amplitude X is the distance between the resting position and the maximum displacement—either the crest or the trough—of the wave. It is important to note that this movement of the wave is actually the disturbance moving to the right, not the water itself; otherwise, the bird would move to the right. Instead, the seagull bobs up and down in place as waves pass underneath, traveling a total distance of 2 X in one cycle. However, as mentioned in the text feature on surfing, actual ocean waves are more complex than this simplified example."],"figures":[{"sourceId":"fs-id1167064744821","filename":"CNX_HSPhysics_13_02_Simple2.jpg","relativePath":"media/CNX_HSPhysics_13_02_Simple2.jpg","alt":"A seagull bobs up and down on a sinusoidal-shaped periodic ocean wave with a given wave velocity of νw. The wavelength λ is shown as the distance from one crest to the next crest. The amplitude X is shown as the distance between the resting position and the crest. The total distance traveled by the seagull in one cycle or period is shown as 2X."}],"tables":[]},{"uid":"hsphys.ch13.sec02.sub02","title":"The Relationship between Wave Frequency, Period, Wavelength, and Velocity","summaryVi":null,"paragraphs":["Since wave frequency is the number of waves per second, and the period is essentially the number of seconds per wave, the relationship between frequency and period is","or","just as in the case of harmonic motion of an object. We can see from this relationship that a higher frequency means a shorter period. Recall that the unit for frequency is hertz (Hz), and that 1 Hz is one cycle—or one wave—per second.","The speed of propagation v w is the distance the wave travels in a given time, which is one wavelength in a time of one period. In equation form, it is written as","or","From this relationship, we see that in a medium where v w is constant, the higher the frequency, the smaller the wavelength. See [Figure 13.2].","These fundamental relationships hold true for all types of waves. As an example, for water waves, v w is the speed of a surface wave; for sound, v w is the speed of sound; and for visible light, v w is the speed of light. The amplitude X is completely independent of the speed of propagation v w and depends only on the amount of energy in the wave.","In this animation, watch how a string vibrates in slow motion by choosing the Slow Motion setting. Select the No End and Manual options, and wiggle the end of the string to make waves yourself. Then switch to the Oscillate setting to generate waves automatically. Adjust the frequency and the amplitude of the oscillations to see what happens. Then experiment with adjusting the damping and the tension.","Which of the settingsamplitude, frequency, damping, or tensionchanges the amplitude of the wave as it propagates? What does it do to the amplitude?"],"figures":[{"sourceId":"fs-id1167065772781","filename":"CNX_HSPhysics_13_02_Speaker.jpg","relativePath":"media/CNX_HSPhysics_13_02_Speaker.jpg","alt":"A smaller speaker emits a high-frequency sound wave with a small wavelength, while a larger speaker emits a lower-frequency sound wave with a larger wavelength."}],"tables":[]}],"workedExamples":[{"uid":"hsphys.ch13.sec02.ex01","number":"13.2.1","title":"Calculate the Velocity of Wave Propagation: Gull in the Ocean","problem":"Calculate the wave velocity of the ocean wave in the previous figure if the distance between wave crests is 10.0 m and the time for a seagull to bob up and down is 5.00 s.","problemImages":[],"strategy":"The values for the wavelength \\((\\lambda = 10.0\\,m)\\) and the period (\nT = 5.00 s) are given and we are asked to find \\({v}_{w}\\) Therefore, we can use \\({v}_{w} = \\frac{\\lambda}{T}\\) to find the wave velocity.","solution":"Enter the known values into \\({v}_{w} = \\frac{\\lambda}{T}\\)\n\\({v}_{w} = \\frac{\\text{10}\\text{.0 m}}{\\text{5}\\text{.00 s}} = 2.\\,\\text{00 m/s}\\text{.}\\)","solutionImages":[],"solutionTables":[],"discussion":"This slow speed seems reasonable for an ocean wave. Note that in the figure, the wave moves to the right at this speed, which is different from the varying speed at which the seagull bobs up and down."},{"uid":"hsphys.ch13.sec02.ex02","number":"13.2.2","title":"Calculate the Period and the Wave Velocity of a Toy Spring","problem":"The woman in [Figure 13.1] creates two waves every second by shaking the toy spring up and down. (a)What is the period of each wave? (b) If each wave travels 0.9 meters after one complete wave cycle, what is the velocity of wave propagation?\nStrategy FOR (A)\nTo find the period, we solve for \\(T = \\frac{1}{f}\\), given the value of the frequency (\nf = 2\ns\n- 1\n).","problemImages":[],"strategy":null,"solution":"Solution for (a)\nEnter the known value into \\(T = \\frac{1}{f}\\)\n\\(T = \\frac{1}{2{\\text{s}}^{-1}} = 0.\\,\\text{5 s}\\text{.}\\)","solutionImages":[],"solutionTables":[],"discussion":"We could have also used the equation \\({v}_{\\text{w}} = \\frac{\\lambda}{T}\\) to solve for the wave velocity since we already know the value of the period (\nT = 0.5 s) from our calculation in part (a), and we would come up with the same answer."}],"snapLabs":[{"uid":"hsphys.ch13.sec02.lab01","title":"Waves in a Bowl","text":"In this lab, you will take measurements to determine how the amplitude and the period of waves are affected by the transfer of energy from a cork dropped into the water. The cork initially has some potential energy when it is held above the water—the greater the height, the higher the potential energy. When it is dropped, such potential energy is converted to kinetic energy as the cork falls. When the cork hits the water, that energy travels through the water in waves.\nLarge bowl or basin\nWater\nCork (or ping pong ball)\nStopwatch\nMeasuring tape\nInstructions\nProcedure Fill a large bowl or basin with water and wait for the water to settle so there are no ripples.\nGently drop a cork into the middle of the bowl.\nEstimate the wavelength and the period of oscillation of the water wave that propagates away from the cork. You can estimate the period by counting the number of ripples from the center to the edge of the bowl while your partner times it. This information, combined with the bowl measurement, will give you the wavelength when the correct formula is used.\nRemove the cork from the bowl and wait for the water to settle again.\nGently drop the cork at a height that is different from the first drop.\nRepeat Steps 3 to 5 to collect a second and third set of data, dropping the cork from different heights and recording the resulting wavelengths and periods.\nInterpret your results.","images":[]}],"tipsAndFeatures":[{"uid":"hsphys.ch13.sec02.feat01","type":"tip","title":"Tips for Success","text":"Wave velocity is sometimes also called the propagation velocity or propagation speed because the disturbance propagates from one location to another.","images":[]},{"uid":"hsphys.ch13.sec02.feat02","type":"tip","title":"Tips for Success","text":"The crest of a wave is sometimes also called the peak .","images":[]},{"uid":"hsphys.ch13.sec02.feat03","type":"physics-in-action","title":"Geology: Physics of Seismic Waves","text":"The destructive effect of an earthquake is a palpable evidence of the energy carried in the earthquake waves. The Richter scale rating of earthquakes is related to both their amplitude and the energy they carry. (Petty Officer 2nd Class Candice Villarreal, U.S. Navy)\nGeologists rely heavily on physics to study earthquakes since earthquakes involve several types of wave disturbances, including disturbance of Earth’s surface and pressure disturbances under the surface. Surface earthquake waves are similar to surface waves on water. The waves under Earth’s surface have both longitudinal and transverse components. The longitudinal waves in an earthquake are called pressure waves (P-waves) and the transverse waves are called shear waves (S-waves). These two types of waves propagate at different speeds, and the speed at which they travel depends on the rigidity of the medium through which they are traveling. During earthquakes, the speed of P-waves in granite is significantly higher than the speed of S-waves. Both components of earthquakes travel more slowly in less rigid materials, such as sediments. P-waves have speeds of 4 to 7 km/s, and S-waves have speeds of 2 to 5 km/s, but both are faster in more rigid materials. The P-wave gets progressively farther ahead of the S-wave as they travel through Earth’s crust. For that reason, the time difference between the P- and S-waves is used to determine the distance to their source, the epicenter of the earthquake.\nWe know from seismic waves produced by earthquakes that parts of the interior of Earth are liquid. Shear or transverse waves cannot travel through a liquid and are not transmitted through Earth’s core. In contrast, compression or longitudinal waves can pass through a liquid and they do go through the core.\nAll waves carry energy, and the energy of earthquake waves is easy to observe based on the amount of damage left behind after the ground has stopped moving. Earthquakes can shake whole cities to the ground, performing the work of thousands of wrecking balls. The amount of energy in a wave is related to its amplitude. Large-amplitude earthquakes produce large ground displacements and greater damage. As earthquake waves spread out, their amplitude decreases, so there is less damage the farther they get from the source.\nWhat is the relationship between the propagation speed, frequency, and wavelength of the S-waves in an earthquake?\nThe relationship between the propagation speed, frequency, and wavelength is \\({v}_{\\text{w}} = f\\lambda .\\)\nThe relationship between the propagation speed, frequency, and wavelength is \\({v}_{\\text{w}} = \\frac{f}{\\lambda}.\\)\nThe relationship between the propagation speed, frequency, and wavelength is \\({v}_{\\text{w}} = \\frac{\\lambda}{f}.\\)\nThe relationship between the propagation speed, frequency, and wavelength is \\({v}_{\\text{w}} = \\sqrt{f\\lambda}.\\)","images":[{"sourceId":"fs-id1167062325676","filename":"CNX_HsPhysics_13_02_Earthquake.jpg","relativePath":"media/CNX_HsPhysics_13_02_Earthquake.jpg","alt":"A town with collapsed buildings after an earthquake."}]}],"summaryPoints":["A wave is a disturbance that moves from the point of creation at a wave velocity v w .","A wave has a wavelength \\(\\lambda\\), which is the distance between adjacent identical parts of the wave.","The wave velocity and the wavelength are related to the wave’s frequency and period by \\({v}_{\\text{w}} = \\frac{\\lambda}{T}\\) or \\({v}_{\\text{w}} = f\\lambda \\text{.}\\)","The time for one complete wave cycle is the period T .","The number of waves per unit time is the frequency ƒ.","The wave frequency and the period are inversely related to one another."],"glossary":[{"term":"wavelength","termVi":"Bước sóng (λ)","definition":"distance between adjacent identical parts of a wave","definitionVi":"Khoảng cách giữa hai đỉnh sóng liên tiếp (hoặc hai điểm gần nhất dao động cùng pha): λ = v / f = v·T.","memoryTipVi":"Đơn vị SI: mét (m)."},{"term":"wave velocity","termVi":"Tốc độ truyền sóng (v)","definition":"speed at which the disturbance moves; also called the propagation velocity or propagation speed","definitionVi":"Tốc độ lan truyền pha dao động trong môi trường: v = λ·f.","memoryTipVi":"Tốc độ sóng cơ chỉ phụ thuộc vào bản chất MÔI TRƯỜNG truyền!"}],"assessments":[{"uid":"hsphys.ch13.sec02.q001","sourceId":"fs-id1167064820992","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"What is the amplitude of a wave?","images":[],"choices":[{"label":"a","text":"A quarter of the total height of the wave"},{"label":"b","text":"Half of the total height of the wave"},{"label":"c","text":"Two times the total height of the wave"},{"label":"d","text":"Four times the total height of the wave"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch13.sec02.q004","sourceId":"fs-id1167064778580","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"When is the wavelength directly proportional to the period of a wave?","images":[],"choices":[{"label":"a","text":"When the velocity of the wave is halved"},{"label":"b","text":"When the velocity of the wave is constant"},{"label":"c","text":"When the velocity of the wave is doubled"},{"label":"d","text":"When the velocity of the wave is tripled"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch13.sec02.q005","sourceId":"fs-id1167066097865","category":"practice-problems","categoryLabel":"Practice Problems (Bài tập vận dụng)","isMultipleChoice":true,"prompt":"The frequency of a wave is 10 Hz. What is its period?","images":[],"choices":[{"label":"a","text":"The period of the wave is 100 s."},{"label":"b","text":"The period of the wave is 10 s."},{"label":"c","text":"The period of the wave is 0.01 s."},{"label":"d","text":"The period of the wave is 0.1 s."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch13.sec02.q006","sourceId":"fs-id1167062476005","category":"practice-problems","categoryLabel":"Practice Problems (Bài tập vận dụng)","isMultipleChoice":true,"prompt":"What is the velocity of a wave whose wavelength is 2 m and whose frequency is 5 Hz?","images":[],"choices":[{"label":"a","text":"20 m/s"},{"label":"b","text":"2.5 m/s"},{"label":"c","text":"0.4 m/s"},{"label":"d","text":"10 m/s"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch13.sec02.q011","sourceId":"fs-id1167066045841","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"If the horizontal distance, that is, the distance in the direction of propagation, between a crest and the adjacent trough of a sine wave is 1 m, what is the wavelength of the wave?","images":[],"choices":[{"label":"a","text":"0.5 m"},{"label":"b","text":"1 m"},{"label":"c","text":"2 m"},{"label":"d","text":"4 m"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch13.sec02.q013","sourceId":"eip-id1166850271470","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"Two identical waves superimpose in pure constructive interference. What is the height of the resultant wave if the amplitude of each of the waves is 1 m?","images":[],"choices":[{"label":"a","text":"1 m"},{"label":"b","text":"2 m"},{"label":"c","text":"3 m"},{"label":"d","text":"4 m"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch13.sec02.q014","sourceId":"fs-id1167066097865","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"The frequency of a wave is 10 Hz. What is its period?","images":[],"choices":[{"label":"a","text":"The period of the wave is 100 s."},{"label":"b","text":"The period of the wave is 10 s."},{"label":"c","text":"The period of the wave is 0.01 s."},{"label":"d","text":"The period of the wave is 0.1 s."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch13.sec02.q015","sourceId":"fs-id1167062476005","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"What is the velocity of a wave whose wavelength is 2 m and whose frequency is 5 Hz?","images":[],"choices":[{"label":"a","text":"20 m/s"},{"label":"b","text":"2.5 m/s"},{"label":"c","text":"0.4 m/s"},{"label":"d","text":"10 m/s"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch13.sec02.q016","sourceId":"fs-id1167062367438","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"If a seagull sitting in water bobs up and down once every 2 seconds and the distance between two crests of the water wave is 3 m, what is the velocity of the wave?","images":[],"choices":[{"label":"a","text":"1.5 m/s"},{"label":"b","text":"3 m/s"},{"label":"c","text":"6 m/s"},{"label":"d","text":"12 m/s"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch13.sec02.q017","sourceId":"fs-id1167062410314","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"A boat in the trough of a wave takes 3 seconds to reach the highest point of the wave. The velocity of the wave is 5 m/s. What is its wavelength?","images":[],"choices":[{"label":"a","text":"0.83 m"},{"label":"b","text":"15 m"},{"label":"c","text":"30 m"},{"label":"d","text":"180 m"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch13.sec02.q018","sourceId":"fs-id1167065878984","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"Which of these is not a characteristic of a wave?","images":[],"choices":[{"label":"a","text":"amplitude"},{"label":"b","text":"period"},{"label":"c","text":"mass"},{"label":"d","text":"velocity"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch13.sec02.q019","sourceId":"fs-id1167065875671","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"If you are in a boat at a resting position, how much will your height change when you are hit by the peak of a wave with a height of 2 m?","images":[],"choices":[{"label":"a","text":"0 m"},{"label":"b","text":"1 m"},{"label":"c","text":"2 m"},{"label":"d","text":"4 m"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch13.sec02.q020","sourceId":"fs-id1167064686969","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"What is the period of a wave with a frequency of 0.5 Hz?","images":[],"choices":[{"label":"a","text":"0.5 s"},{"label":"b","text":"1 s"},{"label":"c","text":"2 s"},{"label":"d","text":"3 s"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch13.sec02.q024","sourceId":"fs-id1167062410609","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"If the amplitude of a water wave is 0.2 m and its frequency is 2 Hz, how much distance would a bird sitting on the waters surface move with every wave? How many times will it do this every second?","images":[],"choices":[{"label":"a","text":"The bird will go up and down a distance of 0.4 m. It will do this twice per second."},{"label":"b","text":"The bird will go up and down a distance of 0.2 m. It will do this twice per second."},{"label":"c","text":"The bird will go up and down a distance of 0.4 m. It will do this once per second."},{"label":"d","text":"The bird will go up and down a distance of 0.2 m. It will do this once per second."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch13.sec02.q028","sourceId":"fs-id1167066127960","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"A water wave propagates in a river at 6 m/s. If the river moves in the opposite direction at 3 m/s, what is the effective velocity of the wave?","images":[],"choices":[{"label":"a","text":"3 m/s"},{"label":"b","text":"6 m/s"},{"label":"c","text":"9 m/s"},{"label":"d","text":"18 m/s"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch13.sec02.q031","sourceId":"fs-id1167062889861","category":"test-prep-er","categoryLabel":"Test Prep — Tự luận mở rộng","isMultipleChoice":true,"prompt":"The time difference between a 2 km/s S-wave and a 6 km/s P-wave recorded at a certain point is 10 seconds. How far is the epicenter of the earthquake from that point?","images":[],"choices":[{"label":"a","text":"15 m"},{"label":"b","text":"30 m"},{"label":"c","text":"15 km"},{"label":"d","text":"30 km"}],"hasOfficialSolution":false,"solution":null}],"stats":{"learningObjectiveCount":3,"keyEquationCount":3,"subsectionCount":2,"workedExampleCount":2,"snapLabCount":1,"glossaryCount":2,"assessmentCount":16}},{"uid":"hsphys.ch13.sec03","moduleId":"m54318","number":"13.3","slug":"wave-interaction-superposition-and-interference","title":"Wave Interaction: Superposition and Interference","isIntroduction":false,"learningObjectives":["Describe superposition of waves","Describe interference of waves and distinguish between constructive and destructive interference of waves","Describe the characteristics of standing waves","Distinguish reflection from refraction of waves"],"bilingualGuide":{"notebookSummaryVi":"Nguyên lý chồng chất, Giao thoa tăng cường / triệt tiêu và Sóng dừng (Nút sóng Nodes & Bụng sóng Antinodes).","wordProblemCues":[{"phraseEn":"nodes / antinodes","meaningVi":"Nút sóng (đứng yên) / Bụng sóng (biên độ max)","mathNotation":"d = λ/2"}],"commonTrapsVi":["Khoảng cách giữa 2 nút liên tiếp (hoặc 2 bụng liên tiếp) là NỬA bước sóng (λ/2), KHÔNG phải 1λ!"]},"keyEquations":[],"subsections":[{"uid":"hsphys.ch13.sec03.sub01","title":"Superposition of Waves","summaryVi":null,"paragraphs":["Most waves do not look very simple. They look more like the waves in [Figure 13.3], rather than the simple water wave considered in the previous sections, which has a perfect sinusoidal shape.","Most waves appear complex because they result from two or more simple waves that combine as they come together at the same place at the same time—a phenomenon called superposition .","Waves superimpose by adding their disturbances; each disturbance corresponds to a force, and all the forces add. If the disturbances are along the same line, then the resulting wave is a simple addition of the disturbances of the individual waves, that is, their amplitudes add."],"figures":[{"sourceId":"fs-id1167067230885","filename":"CNX_HSPhysics_13_03_Superposit.jpg","relativePath":"media/CNX_HSPhysics_13_03_Superposit.jpg","alt":"Waves ripple across a lake by the mountains."}],"tables":[]},{"uid":"hsphys.ch13.sec03.sub02","title":"Wave Interference","summaryVi":null,"paragraphs":["The two special cases of superposition that produce the simplest results are pure constructive interference and pure destructive interference.","Pure constructive interference occurs when two identical waves arrive at the same point exactly in phase. When waves are exactly in phase, the crests of the two waves are precisely aligned, as are the troughs. Refer to [Figure 13.3]. Because the disturbances add, the pure constructive interference of two waves with the same amplitude produces a wave that has twice the amplitude of the two individual waves, but has the same wavelength.","[Figure 13.3] shows two identical waves that arrive exactly out of phase—that is, precisely aligned crest to trough—producing pure destructive interference . Because the disturbances are in opposite directions for this superposition, the resulting amplitude is zero for pure destructive interference; that is, the waves completely cancel out each other.","While pure constructive interference and pure destructive interference can occur, they are not very common because they require precisely aligned identical waves. The superposition of most waves that we see in nature produces a combination of constructive and destructive interferences.","Waves that are not results of pure constructive or destructive interference can vary from place to place and time to time. The sound from a stereo, for example, can be loud in one spot and soft in another. The varying loudness means that the sound waves add partially constructively and partially destructively at different locations. A stereo has at least two speakers that create sound waves, and waves can reflect from walls. All these waves superimpose.","An example of sounds that vary over time from constructive to destructive is found in the combined whine of jet engines heard by a stationary passenger. The volume of the combined sound can fluctuate up and down as the sound from the two engines varies in time from constructive to destructive.","The two previous examples considered waves that are similar—both stereo speakers generate sound waves with the same amplitude and wavelength, as do the jet engines. But what happens when two waves that are not similar, that is, having different amplitudes and wavelengths, are superimposed? An example of the superposition of two dissimilar waves is shown in [Figure 13.3]. Here again, the disturbances add and subtract, but they produce an even more complicated-looking wave. The resultant wave from the combined disturbances of two dissimilar waves looks much different than the idealized sinusoidal shape of a periodic wave.","In this simulation , make waves with a dripping faucet, an audio speaker, or a laser by switching between the water, sound, and light tabs. Contrast and compare how the different types of waves behave. Try rotating the view from top to side to make observations. Then experiment with adding a second source or a pair of slits to create an interference pattern."],"figures":[{"sourceId":"fs-id1167063473771","filename":"CNX_HSPhysics_13_03_Construct.jpg","relativePath":"media/CNX_HSPhysics_13_03_Construct.jpg","alt":"Wave 1 and wave 2 are perfectly in phase, and their resultant has twice the amplitude of each individual wave."},{"sourceId":"fs-id1167063481018","filename":"CNX_HSPhysics_13_03_Destruct.jpg","relativePath":"media/CNX_HSPhysics_13_03_Destruct.jpg","alt":"Wave 1 and wave 2 are perfectly out of phase, and their resultant has zero amplitude."},{"sourceId":"fs-id1167067194400","filename":"CNX_HSPhysics_13_03_Dissimilar.jpg","relativePath":"media/CNX_HSPhysics_13_03_Dissimilar.jpg","alt":"Wave 1 has a large amplitude and a low frequency. Wave 2 has a small amplitude and a high frequency. The resultant is squiggly, without a perfect sinusoidal shape."}],"tables":[]},{"uid":"hsphys.ch13.sec03.sub03","title":"Standing Waves","summaryVi":null,"paragraphs":["Sometimes waves do not seem to move and they appear to just stand in place, vibrating. Such waves are called standing waves and are formed by the superposition of two or more waves moving in opposite directions. The waves move through each other with their disturbances adding as they go by. If the two waves have the same amplitude and wavelength, then they alternate between constructive and destructive interference. Standing waves created by the superposition of two identical waves moving in opposite directions are illustrated in [Figure 13.3].","As an example, standing waves can be seen on the surface of a glass of milk in a refrigerator. The vibrations from the refrigerator motor create waves on the milk that oscillate up and down but do not seem to move across the surface. The two waves that produce standing waves may be due to the reflections from the side of the glass.","Earthquakes can create standing waves and cause constructive and destructive interferences. As the earthquake waves travel along the surface of Earth and reflect off denser rocks, constructive interference occurs at certain points. As a result, areas closer to the epicenter are not damaged while areas farther from the epicenter are damaged.","Standing waves are also found on the strings of musical instruments and are due to reflections of waves from the ends of the string. [Figure 13.3] and [Figure 13.3] show three standing waves that can be created on a string that is fixed at both ends. When the wave reaches the fixed end, it has nowhere else to go but back where it came from, causing the reflection. The nodes are the points where the string does not move; more generally, the nodes are the points where the wave disturbance is zero in a standing wave. The fixed ends of strings must be nodes, too, because the string cannot move there.","The antinode is the location of maximum amplitude in standing waves. The standing waves on a string have a frequency that is related to the propagation speed \\({v}_{w}\\) of the disturbance on the string. The wavelength \\(\\lambda\\) is determined by the distance between the points where the string is fixed in place."],"figures":[{"sourceId":"fs-id1167066974327","filename":"CNX_HSPhysics_13_03_Standing.jpg","relativePath":"media/CNX_HSPhysics_13_03_Standing.jpg","alt":"Two identical waves moving in opposite directions alternate between creating no disturbance during destructive interference and doubling the disturbance during constructive interference."},{"sourceId":"fs-id1167063564014","filename":"CNX_HSPhysics_13_03_Antinode.jpg","relativePath":"media/CNX_HSPhysics_13_03_Antinode.jpg","alt":"One antinode and two nodes are created by a single standing wave."},{"sourceId":"fs-id1167067251762","filename":"CNX_HSPhysics_13_03_Antinodes.jpg","relativePath":"media/CNX_HSPhysics_13_03_Antinodes.jpg","alt":"Two antinodes and three nodes are created by two standing waves. Three antinodes and four nodes are created by three standing waves."}],"tables":[]},{"uid":"hsphys.ch13.sec03.sub04","title":"Reflection and Refraction of Waves","summaryVi":null,"paragraphs":["As we saw in the case of standing waves on the strings of a musical instrument, reflection is the change in direction of a wave when it bounces off a barrier, such as a fixed end. When the wave hits the fixed end, it changes direction, returning to its source. As it is reflected, the wave experiences an inversion , which means that it flips vertically. If a wave hits the fixed end with a crest, it will return as a trough, and vice versa (Henderson 2015). Refer to [Figure 13.3].","Rather than encountering a fixed end or barrier, waves sometimes pass from one medium into another, for instance, from air into water. Different types of media have different properties, such as density or depth, that affect how a wave travels through them. At the boundary between media, waves experience refraction —they change their path of propagation. As the wave bends, it also changes its speed and wavelength upon entering the new medium. Refer to [Figure 13.3].","For example, water waves traveling from the deep end to the shallow end of a swimming pool experience refraction. They bend in a path closer to perpendicular to the surface of the water, propagate slower, and decrease in wavelength as they enter shallower water."],"figures":[{"sourceId":"fs-id1167067036571","filename":"CNX_HSPhysics_13_03_Inversion.jpg","relativePath":"media/CNX_HSPhysics_13_03_Inversion.jpg","alt":"A wave travels to the right, hits the fixed end, flips vertically, and travels to the left."},{"sourceId":"fs-id1167063526214","filename":"CNX_HSPhysics_13_03_Refraction.jpg","relativePath":"media/CNX_HSPhysics_13_03_Refraction.jpg","alt":"A wave bends slightly to the right of its original path as it crosses the line into another medium."}],"tables":[]},{"uid":"hsphys.ch13.sec03.sub05","title":"Performance Task","summaryVi":null,"paragraphs":["Ocean waves repeatedly crash against beaches and coasts. Their energy can lead to erosion and collapse of land. Scientists and engineers need to study how waves interact with beaches in order to assess threats to coastal communities and construct breakwater systems.","In this task, you will construct a wave tank and fill it with water. Simulate a beach by placing sand at one end. Create waves by moving a piece of wood or plastic up and down in the water. Measure or estimate the wavelength, period, frequency, and amplitude of the wave, and observe the effect of the wave on the sand. Produce waves of different amplitudes and frequencies, and record your observations each time. Use mathematical representations to demonstrate the relationships between different wave properties. Change the position of the sand to create a steeper beach and record your observations. Give a qualitative analysis of the effects of the waves on the beach. What kind of wave causes the most damage? At what height, wavelength, and frequency do waves break ? How does the steepness of the beach affect the waves?"],"figures":[],"tables":[]}],"workedExamples":[],"snapLabs":[],"tipsAndFeatures":[{"uid":"hsphys.ch13.sec03.feat01","type":"tip","title":"Tips for Success","text":"If the end is not fixed, it is said to be a free end , and no inversion occurs. When the end is loosely attached, it reflects without inversion, and when the end is not attached to anything, it does not reflect at all. You may have noticed this while changing the settings from Fixed End to Loose End to No End in the Waves on a String PhET simulation.","images":[]}],"summaryPoints":["Superposition is the combination of two waves at the same location.","Constructive interference occurs when two identical waves are superimposed exactly in phase.","Destructive interference occurs when two identical waves are superimposed exactly out of phase.","A standing wave is a wave produced by the superposition of two waves. It varies in amplitude but does not propagate.","The nodes are the points where there is no motion in standing waves.","An antinode is the location of maximum amplitude of a standing wave.","Reflection causes a wave to change direction.","Inversion occurs when a wave reflects from a fixed end.","Refraction causes a wave’s path to bend and occurs when a wave passes from one medium into another medium with a different density."],"glossary":[{"term":"antinode","termVi":"Bụng sóng","definition":"location of maximum amplitude in standing waves","definitionVi":"Các điểm dao động với biên độ cực đại trên sóng dừng.","memoryTipVi":"Nằm chính giữa hai nút sóng liên tiếp."},{"term":"constructive interference","termVi":"Giao thoa tăng cường (Cực đại)","definition":"when two waves arrive at the same point exactly in phase; that is, the crests of the two waves are precisely aligned, as are the troughs","definitionVi":"Hai sóng gặp nhau CÙNG PHA làm biên độ tổng hợp tăng lên cực đại.","memoryTipVi":"Đỉnh gặp đỉnh → sóng cao gấp đôi."},{"term":"destructive interference","termVi":"Giao thoa triệt tiêu (Cực tiểu)","definition":"when two identical waves arrive at the same point exactly out of phase that is precisely aligned crest to trough","definitionVi":"Hai sóng gặp nhau NGƯỢC PHA làm triệt tiêu nhau (biên độ cực tiểu hoặc bằng 0).","memoryTipVi":"Đỉnh gặp hõm → triệt tiêu nhau (ứng dụng trong tai nghe chống ồn ANC!)."},{"term":"inversion","termVi":"Sự đảo pha khi phản xạ","definition":"vertical flipping of a wave after reflection from a fixed end","definitionVi":"Sóng phản xạ bị lộn ngược (ngược pha) khi gặp đầu cố định.","memoryTipVi":"Phản xạ tại đầu cố định → đảo pha; đầu tự do → cùng pha."},{"term":"nodes","termVi":"Nút sóng","definition":"points where the string does not move; more generally, points where the wave disturbance is zero in a standing wave","definitionVi":"Các điểm đứng yên không dao động trên sóng dừng.","memoryTipVi":"Node = No displacement (không dịch chuyển)."},{"term":"reflection","termVi":"Sự phản xạ sóng","definition":"change in direction of a wave at a boundary or fixed end","definitionVi":"Hiện tượng sóng dội ngược lại khi gặp mặt chắn.","memoryTipVi":"Góc tới bằng góc phản xạ."},{"term":"refraction","termVi":"Sự khúc xạ sóng","definition":"bending of a wave as it passes from one medium to another medium with a different density","definitionVi":"Sự đổi hướng lan truyền của sóng khi đi xiên góc qua mặt phân cách giữa hai môi trường có tốc độ truyền khác nhau.","memoryTipVi":"Tần số f KHÔNG ĐỔI khi khúc xạ, chỉ có v và λ thay đổi!"},{"term":"standing wave","termVi":"Sóng dừng","definition":"wave made by the superposition of two waves of the same amplitude and wavelength moving in opposite directions and which appears to vibrate in place","definitionVi":"Sóng tạo bởi sự giao thoa giữa sóng tới và sóng phản xạ, có các điểm đứng yên cố định (nút) và dao động mạnh nhất (bụng).","memoryTipVi":"Khoảng cách giữa 2 nút liên tiếp là λ/2."},{"term":"superposition","termVi":"Nguyên lý chồng chất sóng","definition":"phenomenon that occurs when two or more waves arrive at the same point","definitionVi":"Khi hai hay nhiều sóng gặp nhau, li độ tổng hợp bằng tổng đại số li độ của từng sóng thành phần.","memoryTipVi":"Cơ sở của mọi hiện tượng giao thoa và sóng dừng."}],"assessments":[{"uid":"hsphys.ch13.sec03.q001","sourceId":"fs-id1167063694023","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"What is the superposition of waves?","images":[],"choices":[{"label":"a","text":"When a single wave splits into two different waves at a point"},{"label":"b","text":"When two waves combine at the same place at the same time"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch13.sec03.q002","sourceId":"fs-id1167065877584","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"How do waves superimpose on one another?","images":[],"choices":[{"label":"a","text":"By adding their frequencies"},{"label":"b","text":"By adding their wavelengths"},{"label":"c","text":"By adding their disturbances"},{"label":"d","text":"By adding their speeds"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch13.sec03.q004","sourceId":"fs-id1167066145951","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"Is the following statement true or false? The two types of interference are constructive and destructive interferences.","images":[],"choices":[{"label":"a","text":"True"},{"label":"b","text":"False"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch13.sec03.q005","sourceId":"fs-id1167066026802","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"What are standing waves?","images":[],"choices":[{"label":"a","text":"Waves that appear to remain in one place and do not seem to move"},{"label":"b","text":"Waves that seem to move along a trajectory"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch13.sec03.q012","sourceId":"fs-id1167065843985","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"Is the following statement true or false? Refraction is useful in fiber optic cables for transmitting signals.","images":[],"choices":[{"label":"a","text":"False"},{"label":"b","text":"True"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch13.sec03.q017","sourceId":"fs-id1167066061168","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"What is added together when two waves superimpose?","images":[],"choices":[{"label":"a","text":"Amplitudes"},{"label":"b","text":"Wavelengths"},{"label":"c","text":"Velocities"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch13.sec03.q018","sourceId":"fs-id1167067153829","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"What is added together when two waves superimpose?","images":[],"choices":[{"label":"a","text":"amplitudes"},{"label":"b","text":"wavelengths"},{"label":"c","text":"velocities"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch13.sec03.q019","sourceId":"fs-id1167065821620","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"Pure constructive interference occurs between two waves when they have the same _____.","images":[],"choices":[{"label":"a","text":"frequency and are in phase"},{"label":"b","text":"frequency and are out of phase"},{"label":"c","text":"amplitude and are in phase"},{"label":"d","text":"amplitude and are out of phase"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch13.sec03.q020","sourceId":"fs-id1167065866776","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"What kind(s) of interference can occur between two identical waves moving in opposite directions?","images":[],"choices":[{"label":"a","text":"Constructive interference only"},{"label":"b","text":"Destructive interference only"},{"label":"c","text":"Both constructive and destructive interference"},{"label":"d","text":"Neither constructive nor destructive interference"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch13.sec03.q021","sourceId":"fs-id1167066038274","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"What term refers to the bending of light at the junction of two media?","images":[],"choices":[{"label":"a","text":"interference"},{"label":"b","text":"diffraction"},{"label":"c","text":"scattering"},{"label":"d","text":"refraction"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch13.sec03.q022","sourceId":"eip-id1166847548042","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"Which parameter of a wave gets affected after superposition?","images":[],"choices":[{"label":"a","text":"wavelength"},{"label":"b","text":"direction"},{"label":"c","text":"amplitude"},{"label":"d","text":"frequency"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch13.sec03.q023","sourceId":"eip-id1166850265432","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"When do the amplitudes of two waves get added?","images":[],"choices":[{"label":"a","text":"When their amplitudes are the same"},{"label":"b","text":"When their amplitudes are different"},{"label":"c","text":"When they propagate in perpendicular directions"},{"label":"d","text":"When they are propagating along the same line in opposite directions"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch13.sec03.q026","sourceId":"fs-id1167066042466","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"When does pure destructive interference occur?","images":[],"choices":[{"label":"a","text":"When two waves with equal frequencies that are perfectly in phase and propagating along the same line superimpose."},{"label":"b","text":"When two waves with unequal frequencies that are perfectly in phase and propagating along the same line superimpose."},{"label":"c","text":"When two waves with unequal frequencies that are perfectly out of phase and propagating along the same line superimpose."},{"label":"d","text":"When two waves with equal frequencies that are perfectly out of phase and propagating along the same line superimpose."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch13.sec03.q027","sourceId":"fs-id1167064583720","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"Is this statement true or false? The amplitude of one wave is affected by the amplitude of another wave only when they\nare precisely aligned.","images":[],"choices":[{"label":"a","text":"True"},{"label":"b","text":"False"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch13.sec03.q029","sourceId":"fs-id1167064546132","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"Is the following statement true or false? A standing wave is a superposition of two identical waves that are in phase\nand propagating in the same direction.","images":[],"choices":[{"label":"a","text":"True"},{"label":"b","text":"False"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch13.sec03.q031","sourceId":"fs-id1167065953905","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"Is the statement true or false? Waves propagate faster in a less dense medium if the stiffness is the same.","images":[],"choices":[{"label":"a","text":"True"},{"label":"b","text":"False"}],"hasOfficialSolution":false,"solution":null}],"stats":{"learningObjectiveCount":4,"keyEquationCount":0,"subsectionCount":5,"workedExampleCount":0,"snapLabCount":0,"glossaryCount":9,"assessmentCount":16}}],"summary":{"totalSections":4,"totalKeyEquations":3,"totalWorkedExamples":2,"totalSnapLabs":1,"totalGlossaryTerms":18,"totalAssessments":44,"referencedMediaCount":18},"qualityGate":{"passed":true,"checkedUids":62,"errors":[],"warnings":[]}};
